  "model": "claude-opus-4-7",
  "max_tokens": 1200,
  "system": "Tu es un expert en content marketing B2B pour LinkedIn et Instagram. Tu crées des posts qui génèrent de l'engagement et de la visibilité. Règles :
- LinkedIn : 150-300 mots, 3-5 paragraphes courts, hashtags pertinents (5-8 max), CTA soft en fin
- Instagram : 80-150 mots, plus émotionnel, 20-30 hashtags, storytelling
- Commencer par une accroche forte (question, stat, contre-vérité)
- Pas de jargon inutile
- Valeur concrète pour le lecteur
- CTA naturel (pas commercial)
Retourne un JSON avec les champs : linkedin_post, instagram_post, hashtags_linkedin, hashtags_instagram",
  "messages": [
    {
      "role": "user",
      "content": "Créé un post pour :
Sujet : {{ $json.topic }}
Audience cible : {{ $json.target_audience }}
Ton : {{ $json.tone }}
Mots-clés : {{ $json.keywords }}

Génère les deux versions (LinkedIn + Instagram) au format JSON."
    }
  ]
}

parameters.jsCode:
const claudeResp = $input.item.json;
const plan = $('Récupérer le plan de contenu (DB)').item.json;

let content;
try {
  const text = claudeResp.content[0].text.trim();
  // Extraire le JSON si entouré de markdown
  const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/) || text.match(/({[\s\S]*})/);
  content = JSON.parse(jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : text);
} catch (e) {
  throw new Error('Failed to parse Claude content response: ' + e.message);
}

const linkedinPost = content.linkedin_post + '\n\n' + (content.hashtags_linkedin || []).join(' ');
const instagramPost = content.instagram_post + '\n\n' + (content.hashtags_instagram || []).join(' ');

return [{
  json: {
    ...plan,
    linkedinPost,
    instagramPost,
    rawContent: content,
    dryRun: $vars.DRY_RUN === 'true',
  }
}];

